<template>
  <main class="store-tasks" v-loading="loading">
    <header class="page-header"><div><p class="eyebrow">门店运营 / 任务中心</p><h1>门店任务</h1><p>设计一次表单，按门店下发日常任务或限时任务；成员共同填写，审核记录可追溯。</p></div><el-button @click="load">刷新</el-button></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="space" />
    <el-tabs v-model="tab">
      <el-tab-pane v-if="can('store-tasks.manage')" label="项目与表单" name="templates">
        <StoreTaskTemplateList :templates="templates" :store-counts="storeCounts" @edit="edit" @new="newProject({title:'',description:'',questions:[]})" @dispatch="openDispatch" @plans="openStores" />
      </el-tab-pane>
      <el-tab-pane label="执行与审核" name="progress" lazy><el-radio-group v-model="progressView" class="space"><el-radio-button value="tasks">任务进度</el-radio-button><el-radio-button value="submissions">提交与审核</el-radio-button></el-radio-group><p class="view-purpose">{{progressView==='tasks'?'按任务查看各门店执行情况，包含尚未提交、逾期和已完成的任务。':'按每次提交查看冻结版本、审核与回执；驳回后重提会保留独立记录。'}}</p><StoreTaskSubmissionReview v-if="progressView==='submissions'" ref="submissionView" :stores="config.stores" :can-review="can('store-tasks.review')" /><template v-else>
        <div class="filters"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" :clearable="false" /><StoreRegionSelect v-model="storeId" clearable placeholder="全部授权门店" :stores="config.stores" restrict-to-stores /><el-button @click="loadRows">查询</el-button></div>
        <div class="metrics"><div v-for="s in ['draft','pending','approved','rejected','missed','forfeited']" :key="s"><span>{{ status(s) }}</span><strong>{{ rows.filter(r=>(r.effective_status||r.status)===s).length }}</strong></div></div>
        <el-table :data="rows" stripe><el-table-column prop="store_name" label="门店" min-width="180" /><el-table-column prop="title" label="任务" min-width="140"><template #default="{row}"><strong>{{row.title}}</strong><small v-if="row.task_kind==='windowed'" class="table-sub">限时 · 已通过 {{row.approved_count}}/{{row.target_count}} 次</small></template></el-table-column><el-table-column prop="business_date" label="开始日期" width="120" /><el-table-column label="状态" width="140"><template #default="{row}"><el-tag :type="tone(row.effective_status||row.status)">{{ status(row.effective_status||row.status) }}</el-tag><small v-if="row.execution?.phase==='blocked'||row.execution?.phase==='not_started'" class="table-sub">{{row.execution.reason}}</small></template></el-table-column><el-table-column label="表单进度" min-width="150"><template #default="{row}">已填 {{row.completed}} / {{row.total}} 项</template></el-table-column><el-table-column prop="contributors" label="参与人数" width="100" /><el-table-column label="截止时间" min-width="170"><template #default="{row}">{{ fmt(row.due_at) }}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="openTask(row.id)">查看任务</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="本时间范围暂无任务，请先下发表单" /><p v-if="rows.length>=1000" class="muted">结果较多，仅显示前1000份任务，请缩小日期或门店范围。</p>
      </template></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="editorOpen" fullscreen destroy-on-close :close-on-click-modal="false" :before-close="closeEditor" title="编辑表单">
      <StoreTaskFormDesigner v-if="editorOpen" ref="designerRef" :editor="editor" :templates="templates" :busy="busy" @edit="edit" @new="newProject" @save="save" />
    </el-dialog>
    <el-drawer v-model="dispatchOpen" size="min(820px,96vw)" title="下发任务" :close-on-click-modal="false">
      <section class="dispatch-panel">
        <div class="dispatch-intro"><span class="step">01 / 03</span><h2>选择任务类型</h2><p>表单内容保持一致，下发规则决定门店何时填写、何时截止。</p></div>
        <el-segmented v-model="dispatchForm.task_kind" :options="[{label:'日常 / 周期任务',value:'routine'},{label:'限时一次或多次',value:'windowed'}]" class="kind-switch" />
        <el-form label-position="top" class="dispatch-form">
          <div class="dispatch-section"><span class="step">02 / 03</span><h3>任务与门店</h3>
            <el-form-item label="任务表单"><el-select v-model="dispatchForm.template_id" style="width:100%" filterable><el-option v-for="t in templates" :key="t.id" :label="t.title" :value="t.id" /></el-select></el-form-item>
            <el-form-item label="执行门店"><StoreRegionSelect v-model="dispatchForm.store_ids" :stores="config.stores" multiple restrict-to-stores input-width="100%" placeholder="按区域或门店选择" /></el-form-item>
          </div>
          <div class="dispatch-section"><span class="step">03 / 03</span><h3>执行规则</h3>
            <template v-if="dispatchForm.task_kind==='windowed'">
              <p class="section-help">每店共享一份任务，在时间窗内完成指定次数；每次提交审核通过后计入一次。</p>
              <el-form-item label="可执行日期范围（北京时间）"><el-date-picker v-model="dispatchRange" type="daterange" value-format="YYYY-MM-DD" :clearable="false" style="width:100%" /></el-form-item>
              <div class="form-pair"><el-form-item label="首日开始时间"><el-time-select v-model="dispatchForm.opens_time" start="00:00" end="23:30" step="00:30" style="width:100%" /></el-form-item><el-form-item label="末日截止时间"><el-time-select v-model="dispatchForm.due_time" start="00:00" end="23:30" step="00:30" style="width:100%" /></el-form-item></div>
              <el-form-item label="每店需要完成"><el-input-number v-model="dispatchForm.target_count" :min="1" :max="30" /><span class="field-suffix">次，审核通过才计数</span></el-form-item>
              <el-alert type="info" :closable="false" title="截止前未达标的剩余次数按弃权；按时提交的记录可以在截止后审核。" />
            </template>
            <template v-else>
              <el-form-item label="重复周期"><el-radio-group v-model="dispatchForm.frequency"><el-radio-button value="once">单日一次</el-radio-button><el-radio-button value="daily">每日</el-radio-button><el-radio-button value="weekly">每周</el-radio-button><el-radio-button value="monthly">每月</el-radio-button></el-radio-group></el-form-item>
              <el-form-item v-if="dispatchForm.frequency==='weekly'" label="每周执行日"><el-select v-model="dispatchForm.weekday" style="width:100%"><el-option v-for="d in weekdays" :key="d.value" :label="d.label" :value="d.value" /></el-select></el-form-item>
              <el-form-item v-if="dispatchForm.frequency!=='once'" label="生效方式"><el-radio-group v-model="dispatchForm.long_term"><el-radio-button :value="true">长期生效</el-radio-button><el-radio-button :value="false">指定日期范围</el-radio-button></el-radio-group></el-form-item>
              <el-form-item v-if="dispatchForm.frequency==='once'||dispatchForm.long_term" label="开始日期"><el-date-picker v-model="dispatchRange[0]" type="date" value-format="YYYY-MM-DD" :clearable="false" /></el-form-item>
              <el-form-item v-else label="生成日期范围（最多93天）"><el-date-picker v-model="dispatchRange" type="daterange" value-format="YYYY-MM-DD" :clearable="false" style="width:100%" /></el-form-item>
              <div class="form-pair"><el-form-item label="当天可填写时间"><el-time-select v-model="dispatchForm.opens_time" start="00:00" end="23:30" step="00:30" style="width:100%" /></el-form-item><el-form-item label="当天截止时间"><el-time-select v-model="dispatchForm.due_time" start="00:00" end="23:30" step="00:30" style="width:100%" /></el-form-item></div>
              <el-form-item label="开始前置条件（可选）"><el-select v-model="dispatchForm.depends_on_template_id" clearable filterable placeholder="无前置任务" style="width:100%"><el-option v-for="t in templates.filter(t=>t.id!==dispatchForm.template_id)" :key="t.id" :label="t.title" :value="t.id" /></el-select></el-form-item>
              <el-form-item v-if="dispatchForm.depends_on_template_id" label="解锁条件"><el-radio-group v-model="dispatchForm.dependency_gate"><el-radio-button value="submitted">前置任务已提交</el-radio-button><el-radio-button value="approved">前置任务审核通过</el-radio-button></el-radio-group></el-form-item>
            </template>
          </div>
        </el-form>
        <div class="dispatch-summary"><strong>下发预览</strong><p>{{ dispatchPreview }}</p><small>下发后，已有填写与审核记录不会被覆盖。</small></div>
        <div class="dispatch-actions"><el-button @click="dispatchOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="publish">确认下发</el-button></div>
        <el-alert v-if="dispatchResult" :title="dispatchResult" type="success" :closable="false" class="space" />
      </section>
    </el-drawer>
    <el-drawer v-model="plansOpen" size="min(1050px,96vw)" title="门店管理" destroy-on-close><StoreTaskStores v-if="managedTemplate" :template="managedTemplate" @changed="loadPlans" @view-task="viewManagedTask" /></el-drawer>
    <el-drawer v-model="drawer" size="min(760px,95vw)" title="门店任务 · 共同执行" @closed="task=null">
      <template v-if="task"><header class="task-heading"><div class="task-heading-top"><div><span class="step">{{task.task_kind==='windowed'?'阶段性任务':'周期任务'}}</span><h2>{{ task.title }}</h2><p>{{ task.store_name }}</p></div><el-tag :type="tone(task.effective_status||task.status)">{{ status(task.effective_status||task.status) }}</el-tag></div><div class="task-facts"><div><small>开始</small><strong>{{ fmt(task.opens_at) }}</strong></div><div><small>截止</small><strong>{{ fmt(task.due_at) }}</strong></div><div><small>{{task.task_kind==='windowed'?'已通过次数':'已填写项目'}}</small><strong>{{task.task_kind==='windowed'?task.approved_count+' / '+task.target_count:task.completed+' / '+task.total}}</strong></div></div><p v-if="task.description" class="task-description">{{ task.description }}</p><el-alert v-if="task.execution?.reason" :title="task.execution.reason" :type="task.execution.phase==='forfeited'||task.execution.phase==='missed'?'error':'info'" :closable="false" /><el-alert v-if="task.execution?.reopened" :title="'补填已开放至 '+fmt(task.execution.reopen_until)" type="warning" :closable="false" /><div class="task-toolbar"><span>全店共享进度，审核记录保留</span><el-button @click="reloadDetail(false)">刷新进度</el-button></div></header>
        <el-alert v-if="task.status==='rejected'" :title="`审核退回：${task.submissions[0]?.review_note}`" type="warning" :closable="false" />
        <div v-if="['forfeited','missed'].includes(task.effective_status)&&!task.execution?.reopened&&(can('store-tasks.manage')||can('store-tasks.review'))" class="reopen-panel"><h3>授权补填</h3><p>只开放当前门店的这份任务。原截止时间与逾期记录保留。</p><el-input v-model="reopenReason" maxlength="500" show-word-limit placeholder="填写补填原因" /><el-date-picker v-model="reopenUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="选择补填截止时间" /><el-button type="primary" :disabled="!reopenReason.trim()||!reopenUntil" :loading="busy" @click="grantReopen">确认授权</el-button></div>
        <article v-for="(q,index) in task.results" :key="q.id" class="question-card"><h3><span v-if="q.required" class="required">*</span> {{ String(index+1).padStart(2,'0') }} {{ q.title }}</h3><StoreTaskInstructions :text="q.description" :images="q.guide_images||[]" /><el-tag size="small">{{q.execution_mode==='single'?'单人完成':'多人共同完成'}}</el-tag> <el-tag size="small" :type="q.conflict?'danger':q.complete?'success':'info'">{{ q.conflict?'结果不一致，请协调后修改':q.complete?'已填写':'待填写' }}</el-tag>
          <p v-if="q.owner" class="muted">{{q.complete?'实际完成人':'正在填写'}}：{{q.owner.name}} · 其他成员可查看</p><p v-else-if="q.complete" class="muted">实际完成人：{{(q.completed_by||[]).map(a=>a.name).join('、')}}</p>
          <div class="contribution" v-for="a in q.contributions" :key="a.id"><strong>{{ a.user_name }}</strong> <small>{{ fmt(a.created_at) }}</small><p v-if="a.response.value">{{ displayValue(q,a.response.value) }}</p><StoreTaskPhoto v-for="image in a.response.images" :key="image" :path="image"/><span v-if="!a.response.value && !a.response.images.length" class="muted">已清空本人内容</span></div>
          <div v-if="canAnswer(q)" class="answer-form"><label>我的填写</label><template v-if="q.type==='photo'"><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="upload(q,$event)" /><p>合计要求 {{ q.min }}—{{ q.max }} 张；我的待保存照片 {{ answers[q.id]?.images.length || 0 }} 张</p><div v-for="(image,i) in answers[q.id]?.images" :key="image"><StoreTaskPhoto :path="image"/><el-button link type="danger" @click="answers[q.id].images.splice(i,1)">移除本人照片</el-button></div></template><el-select v-else-if="['choice','dropdown'].includes(q.type)" v-model="answers[q.id].value" clearable><el-option v-for="option in q.options" :key="option" :label="option" :value="option" /></el-select><el-select v-else-if="q.type==='multiple'" :model-value="multi(answers[q.id].value)" multiple @update:model-value="answers[q.id].value=JSON.stringify($event)"><el-option v-for="option in q.options" :key="option" :label="option" :value="option" /></el-select><el-date-picker v-else-if="q.type==='date'" v-model="answers[q.id].value" type="date" value-format="YYYY-MM-DD" placeholder="选择日期" /><el-input v-else v-model="answers[q.id].value" :type="q.type==='text'&&q.multiline!==false?'textarea':'text'" :maxlength="q.maxLength||2000" :placeholder="q.placeholder||'请输入'" :inputmode="q.type==='number'?'decimal':'text'" /><el-button type="primary" plain :loading="busy" @click="saveAnswer(q)">保存此项</el-button></div>
        </article>
        <el-button v-if="can('store-tasks.execute') && task.execution?.can_edit" type="primary" :loading="busy" @click="submit">提交整份任务审核</el-button>

        <h3>提交与审核历史</h3><el-collapse><el-collapse-item v-for="record in task.submissions" :key="record.id" :title="`第${record.version}版 · ${status(record.status)}${record.late_submission?' · 授权补填':''} · ${record.submitted_name} · ${fmt(record.submitted_at)}`" :name="record.id"><p>审核人：{{ record.reviewed_name || '待审核' }} · {{ record.review_note || '暂无意见' }}</p><div v-for="q in record.snapshot" :key="q.id"><strong>{{ q.title }}</strong><StoreTaskInstructions :text="q.description" :images="q.guide_images||[]" /><p v-for="a in q.contributions" :key="a.id">{{ a.user_name }}：{{ displayValue(q,a.response.value) }}<StoreTaskPhoto v-for="image in a.response.images" :key="image" :path="image"/></p></div></el-collapse-item></el-collapse>
      </template>
    </el-drawer>
    <el-dialog v-model="photoDialog" title="任务照片" width="min(700px,95vw)"><img v-if="photo" :src="photo" alt="成员提交的任务照片" style="width:100%;max-height:70vh;object-fit:contain" /></el-dialog>
  </main>
</template>
<script setup>
import { reactive, ref, computed, onMounted, onBeforeUnmount, defineAsyncComponent } from 'vue'
import StoreTaskTemplateList from '@/components/StoreTaskTemplateList.vue'
import StoreTaskStores from '@/components/StoreTaskStores.vue'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import StoreTaskInstructions from '@/components/StoreTaskInstructions.vue'
import StoreTaskPhoto from '@/components/StoreTaskPhoto.vue'
import StoreTaskSubmissionReview from '@/components/StoreTaskSubmissionReview.vue'
const StoreTaskFormDesigner=defineAsyncComponent(()=>import('@/components/StoreTaskFormDesigner.vue'))
import { ElMessage, ElMessageBox } from 'element-plus'
import { storeTaskApi } from '@/api'
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const tab=ref('templates'), config=reactive({stores:[],permissions:[]}), templates=ref([]), editor=reactive({title:'',description:'',questions:[]}), rows=ref([]), range=ref([today(),today()]), storeId=ref(null), loading=ref(false), busy=ref(false), error=ref(''), dispatchResult=ref('')
const dispatchForm=reactive({template_id:null,store_ids:[],task_kind:'routine',frequency:'daily',opens_time:'00:00',due_time:'10:00',target_count:1,long_term:true,enforce_time:true,weekday:null,depends_on_template_id:null,dependency_gate:'submitted'}), dispatchRange=ref([today(),today()]), storeCounts=ref([]),managedTemplate=ref(null)
const weekdays=[{label:'周一',value:1},{label:'周二',value:2},{label:'周三',value:3},{label:'周四',value:4},{label:'周五',value:5},{label:'周六',value:6},{label:'周日',value:0}]
const dispatchPreview=computed(()=>{const name=templates.value.find(t=>t.id===dispatchForm.template_id)?.title||'尚未选择表单',stores=dispatchForm.store_ids.length;if(dispatchForm.task_kind==='windowed')return `${name} · ${stores} 家门店 · ${dispatchRange.value?.[0]||'—'} ${dispatchForm.opens_time||'—'} 至 ${dispatchRange.value?.[1]||'—'} ${dispatchForm.due_time||'—'} · 每店审核通过 ${dispatchForm.target_count} 次`;const cycle={once:'单日',daily:'每日',weekly:`每周${weekdays.find(d=>d.value===dispatchForm.weekday)?.label||'指定日'}`,monthly:'每月'}[dispatchForm.frequency];return `${name} · ${stores} 家门店 · ${cycle}执行 · ${dispatchForm.opens_time||'00:00'} 开始，${dispatchForm.due_time||'—'} 截止${dispatchForm.depends_on_template_id?' · 有前置任务':''}`})
const progressView=ref('tasks'),submissionView=ref(null)
const editorOpen=ref(false),dispatchOpen=ref(false),plansOpen=ref(false),designerRef=ref(null)
const drawer=ref(false), task=ref(null), answers=reactive({}), reviewNote=ref(''), reopenReason=ref(''), reopenUntil=ref(''), photoDialog=ref(false), photo=ref('')
function multi(v){try{return JSON.parse(v||'[]')}catch{return []}}
function displayValue(q,v){return q.type==='multiple'?multi(v).join('、'):v}
const can=code=>config.permissions.includes('*')||config.permissions.includes(code)
const canAnswer=q=>can('store-tasks.execute')&&task.value?.execution?.can_edit&&(q.execution_mode!=='single'||!q.owner||q.owner.id===currentUserId)
let progressTimer,detailRequest=0
onBeforeUnmount(()=>clearInterval(progressTimer))
onMounted(()=>{progressTimer=setInterval(()=>{if(drawer.value&&task.value?.id&&!busy.value&&!document.hidden)reloadDetail(false,true)},5000)})
let currentUserId=0
const status=s=>({draft:'待提交',pending:'待审核',approved:'已通过',rejected:'已退回',forfeited:'逾期弃权',missed:'超时未提交'}[s]||s), tone=s=>({pending:'warning',approved:'success',rejected:'danger',forfeited:'danger',missed:'danger'}[s]||'info')
const fmt=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
async function attempt(fn){busy.value=true;error.value='';try{await fn()}catch(e){if(e!=='cancel'&&e!=='close'){error.value=e.message||'操作失败';ElMessage.error(error.value)}}finally{busy.value=false}}
function edit(item){Object.keys(editor).forEach(k=>delete editor[k]);Object.assign(editor,JSON.parse(JSON.stringify(item)));editorOpen.value=true}
function newProject(draft){edit(draft?.questions ? draft : config.seed)}
async function closeEditor(done){if(busy.value)return;if(!designerRef.value||await designerRef.value.discard())done()}
function openDispatch(item){Object.assign(dispatchForm,{template_id:item.id,store_ids:[],task_kind:'routine',frequency:'daily',opens_time:'00:00',due_time:'10:00',target_count:1,long_term:true,enforce_time:true,weekday:null,depends_on_template_id:null,dependency_gate:'submitted'});dispatchRange.value=[today(),today()];dispatchResult.value='';dispatchOpen.value=true}
async function load(){loading.value=true;error.value='';try{Object.assign(config,await storeTaskApi.config());currentUserId=config.user_id; if(can('store-tasks.manage')){templates.value=(await storeTaskApi.templates()).templates;}else tab.value='progress';await loadRows();await loadPlans();await submissionView.value?.load()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadRows(){try{rows.value=(await storeTaskApi.list({from:range.value[0],to:range.value[1],store_id:storeId.value})).rows}catch(e){rows.value=[];error.value=e.message}}
async function save(){await attempt(async()=>{
  if(!editor.title?.trim())throw new Error('请填写项目名称')
  if(!editor.questions.length)throw new Error('请至少添加一个问题')
  for(const [i,q] of editor.questions.entries()){
    const n=String(i+1).padStart(2,'0')
    if(!q.title?.trim())throw new Error(`请填写第${n}题的问题标题`)
    if(q.type==='choice'){
      const options=(q.options || []).map(v=>v.trim()).filter(Boolean)
      if(options.length<2||new Set(options).size!==q.options.length)throw new Error(`第${n}题请设置至少两个不为空、不重复的选项`)
    }
    if(q.type==='photo'&&(q.min>q.max||q.min==null||q.max==null))throw new Error(`第${n}题请设置正确的图片数量`)
  }
  const {id}=await storeTaskApi.save(editor);templates.value=(await storeTaskApi.templates()).templates;edit(templates.value.find(t=>t.id===id));dispatchForm.template_id=id;ElMessage.success('项目已保存')
})}
async function publish(){await attempt(async()=>{if(!dispatchForm.template_id||!dispatchForm.store_ids.length)throw new Error('请选择任务表单和执行门店');const windowed=dispatchForm.task_kind==='windowed',long=!windowed&&dispatchForm.long_term&&dispatchForm.frequency!=='once',from=dispatchRange.value?.[0],to=windowed||!long&&dispatchForm.frequency!=='once'?dispatchRange.value?.[1]:from;if(!from||!to)throw new Error('请选择完整执行日期');if(!dispatchForm.opens_time||!dispatchForm.due_time)throw new Error('请设置开始与截止时间');if(windowed&&Date.parse(`${from}T${dispatchForm.opens_time}:00+08:00`)>=Date.parse(`${to}T${dispatchForm.due_time}:00+08:00`))throw new Error('截止时间必须晚于开始时间');if(!windowed&&dispatchForm.opens_time>=dispatchForm.due_time)throw new Error('当天截止时间必须晚于开始时间');await ElMessageBox.confirm(dispatchPreview.value+'。确认下发？','核对任务规则',{confirmButtonText:'确认下发',cancelButtonText:'返回检查'});const result=await storeTaskApi.dispatch({...dispatchForm,frequency:windowed?'once':dispatchForm.frequency,long_term:long,from,to});dispatchResult.value=long?`已启用 ${result.schedules} 家门店的长期计划`:`已创建 ${result.created} 份任务；${result.existing} 份已存在并保留`;range.value=long?[today(),today()]:[from,to];await loadRows();await loadPlans()})}
async function loadPlans(){if(can('store-tasks.manage'))storeCounts.value=(await storeTaskApi.storeSummary()).rows}
function openStores(template){managedTemplate.value=template;plansOpen.value=true}
function viewManagedTask(id){plansOpen.value=false;openTask(id)}
async function openTask(id){drawer.value=true;task.value={id,results:[],submissions:[]};reopenReason.value='';reopenUntil.value='';Object.keys(answers).forEach(k=>delete answers[k]);await reloadDetail(true)}
async function reloadDetail(reset,quiet=false){const id=task.value?.id,request=++detailRequest;if(!id)return;try{const data=await storeTaskApi.detail(id);if(request!==detailRequest||!drawer.value||task.value?.id!==id)return;task.value=data.task;const listed=rows.value.find(r=>r.id===id);if(listed)Object.assign(listed,{completed:data.task.completed,total:data.task.total,in_progress:data.task.total-data.task.completed,status:data.task.status,effective_status:data.task.effective_status,approved_count:data.task.approved_count,execution:data.task.execution});for(const q of task.value.results){if(reset||!answers[q.id]){const own=q.contributions.find(a=>a.user_id===currentUserId);answers[q.id]=JSON.parse(JSON.stringify(own?.response||{value:'',images:[]}))}}}catch(e){if(!quiet)ElMessage.error(e.message)}}
async function grantReopen(){await attempt(async()=>{await storeTaskApi.reopen(task.value.id,{reason:reopenReason.value,expires_at:new Date(reopenUntil.value+'+08:00').toISOString()});reopenReason.value='';reopenUntil.value='';await reloadDetail(false);await loadRows();ElMessage.success('已授权补填')})}
async function upload(q,event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await attempt(async()=>{if(file.size>50*1024*1024)throw new Error('照片最多50MB');if(answers[q.id].images.length>=q.max)throw new Error('已达到本人照片数量上限');const result=await storeTaskApi.uploadFile(task.value.id,file);answers[q.id].images.push(result.path)})}
async function saveAnswer(q){await attempt(async()=>{await storeTaskApi.answer(task.value.id,{question_id:q.id,revision:task.value.revision,...answers[q.id]});await reloadDetail(false);answers[q.id]=JSON.parse(JSON.stringify(task.value.results.find(r=>r.id===q.id).contributions.find(a=>a.user_id===currentUserId).response));ElMessage.success('已保存，其他成员可查看')})}
async function submit(){await attempt(async()=>{if(task.value.results.some(q=>canAnswer(q)&&JSON.stringify(answers[q.id])!==JSON.stringify(q.contributions.find(a=>a.user_id===currentUserId)?.response||{value:'',images:[]})))throw new Error('还有未保存的填写，请先保存各题内容');await ElMessageBox.confirm('请先保存各题内容。提交后本版冻结，等待审核。','提交审核');await storeTaskApi.submit(task.value.id,{revision:task.value.revision});await reloadDetail(false);await loadRows()})}
async function review(status){await attempt(async()=>{await storeTaskApi.review(task.value.id,{status,note:reviewNote.value,version:task.value.submissions[0].version});reviewNote.value='';await reloadDetail(false);await loadRows()})}
async function showPhoto(path){await attempt(async()=>{photo.value=(await storeTaskApi.photo(path)).data;photoDialog.value=true})}
onMounted(load)
</script>
